package org.sou1.audio;
import java.io.IOException;import java.io.InputStream;import java.io.InterruptedIOException;import java.security.MessageDigest;import java.security.NoSuchAlgorithmException;
/** Background-only exact bundled PCM reader/resampler. No network or Android decoder dependency. */
public final class NativeWeatherBankLoader {
 private NativeWeatherBankLoader(){}
 private static void check()throws InterruptedIOException{if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Weather preparation cancelled");}
 private static byte[] verified(NativeMelodicBankLoader.AssetReader reader,String file,int size,String hash)throws IOException{check();if(size<44||size>1024*1024)throw new IOException("Weather budget");byte[] b=new byte[size];try(InputStream in=reader.open("weather-assets/"+file)){int at=0;while(at<size){check();int n=in.read(b,at,Math.min(8192,size-at));if(n<0)throw new IOException("Truncated weather");if(n==0){int v=in.read();if(v<0)throw new IOException("Truncated weather");b[at++]=(byte)v;}else at+=n;}if(in.read()!=-1)throw new IOException("Oversized weather");}try{StringBuilder h=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(b))h.append(Character.forDigit((v>>>4)&15,16)).append(Character.forDigit(v&15,16));if(!hash.equals(h.toString()))throw new IOException("Weather integrity mismatch");}catch(NoSuchAlgorithmException e){throw new IOException(e);}return b;}
 private static int u16(byte[] b,int p){return(b[p]&255)|((b[p+1]&255)<<8);}private static long u32(byte[] b,int p){return Integer.toUnsignedLong(u16(b,p)|(u16(b,p+2)<<16));}private static boolean tag(byte[] b,int p,String s){for(int i=0;i<s.length();i++)if(b[p+i]!=(byte)s.charAt(i))return false;return true;}
 public static RecordedWeather.Bank prepare(int rate,NativeMelodicBankLoader.AssetReader reader)throws IOException{if(rate<8000||rate>192000||reader==null)throw new IllegalArgumentException("Weather reader/rate");verified(reader,"manifest.json",NativeWeatherCatalog.MANIFEST_BYTES,NativeWeatherCatalog.MANIFEST_HASH);float[][] samples=new float[3][];for(int i=0;i<3;i++){NativeWeatherCatalog.Spec s=NativeWeatherCatalog.SAMPLES[i];byte[] b=verified(reader,s.file,s.bytes,s.hash);if(b.length!=44+s.frames*2||!tag(b,0,"RIFF")||u32(b,4)!=b.length-8||!tag(b,8,"WAVE")||!tag(b,12,"fmt ")||u32(b,16)!=16||u16(b,20)!=1||u16(b,22)!=1||u32(b,24)!=s.rate||u32(b,28)!=s.rate*2L||u16(b,32)!=2||u16(b,34)!=16||!tag(b,36,"data")||u32(b,40)!=s.frames*2L)throw new IOException("Weather WAV format");float[] pcm=new float[s.frames];for(int n=0;n<pcm.length;n++){if((n&8191)==0)check();pcm[n]=(short)u16(b,44+n*2)/32768.0f;}samples[i]=resample(pcm,s.rate/(double)rate,s.loop);}check();return new RecordedWeather.Bank(rate,samples);}
 private static float[] resample(float[] pcm,double step,boolean loop)throws IOException{int n=(int)StrictMath.ceil(pcm.length/step);float[] out=new float[n];double cut=.92*Math.min(1,1/step);for(int i=0;i<n;i++){if((i&4095)==0)check();double pos=i*step;int base=(int)StrictMath.floor(pos);double sum=0,weights=0;for(int j=base-7;j<=base+8;j++){double d=pos-j;if(Math.abs(d)>=8)continue;double x=d*cut,w=cut*(Math.abs(x)<1e-9?1:StrictMath.sin(Math.PI*x)/(Math.PI*x))*(.5+.5*StrictMath.cos(Math.PI*d/8));weights+=w;if(loop||j>=0&&j<pcm.length)sum+=pcm[loop?Math.floorMod(j,pcm.length):j]*w;}out[i]=(float)(Math.abs(weights)>1e-9?sum/weights:0);}return out;}
}
